/// <summary>
/// CoC - Extension of class AVADAIReportExportRunContoller to extend metadata default values for each report
/// </summary>
[ExtensionOf(classStr(AVADAIReportExportRunContoller))]
final class AVADAIReportExportRunContoller_cls_Extension
{
}

Method.Source:
/// <summary>
/// CoC - Pre export data functionality to create metadata default values
/// </summary>
/// <returns>Boolean - True is export data was successfully</returns>
protected boolean exportData()
{
    if (toExport)
    {
        this.processingMetaDataDefaultValues();
    }

    return next exportData();
}

/// <summary>
/// Process metadata default values
/// </summary>
private void processingMetaDataDefaultValues()
{
    AVADAIReport reportSetup = dmsService.getReportSetup();

    AVADAIReportMetadataDefaultValues metadataDefaultValues;
    while select metadataDefaultValues
        where metadataDefaultValues.MetaDataId == reportSetup.MetaDataId
    {
        this.createDefaultValueExportLine(metadataDefaultValues);
    }
}

/// <summary>
/// Save value from DP or query.
/// </summary>
/// <param name = "_metadataDefaultValues">AVADAIMetaReportMetadataDefaultValues record</param>
private void createDefaultValueExportLine(AVADAIReportMetadataDefaultValues _metadataDefaultValues)
{
    AVADAIReportExportLine line;
    line.clear();
    line.ExportId = exportId;
    line.Table = 'Default';
    line.FieldMethod = _metadataDefaultValues.Alias;
    line.IsMethod = NoYes::No;
    line.Alias = _metadataDefaultValues.Alias;
    line.RefRecId = _metadataDefaultValues.RecId;
    line.value = _metadataDefaultValues.Value;

    exportLine.add(line);
}
